%% Figure 6 A1/A2: best-method map and b-error map, eta = 1.
%
% Solves the buffer problem on a 100-by-100 (lambda, nu) grid with an
% 800-point radial grid, compares five approximations and colours every
% parameter pair with the method of smallest r-averaged b error.
%
% b0(lambda, nu) is regenerated by BUFFER.GENERATEB0GRID at run time;
% nothing is written to disk.
%
% Output: figures/figure6A1A2_winnerMap.png
%         figures/figure6A1A2_errorMap.png

clear; close all; clc;

figureDir = fileparts(mfilename('fullpath'));
addpath(fullfile(figureDir, '..'));
outDir = buffer.outputDir();

eta           = 1;
nGrid         = 800;
nLambda       = 100;
nNu           = 100;
tolerance     = 1e-3;
stepTolerance = 1e-12;
maxIterations = 500;

lambdaValues = logspace(-3, 2, nLambda)';
nuValues     = logspace(-3, 2, nNu)';
grid         = buffer.geometricGrid(1e-3, 1e2, nGrid);
b0           = buffer.generateB0Grid( ...
    lambdaValues, nuValues, eta, 'Verbose', false);

bNum = buffer.solveGeometricLambdaGrid(b0, lambdaValues, nuValues, ...
    eta, grid, 'Tolerance', tolerance, 'StepTolerance', stepTolerance, ...
    'MaxIterations', maxIterations, 'Verbose', false);

methodNames = {'Pade2', 'RBA2', 'Exp-Pade', 'DblExp-Global', 'Exp-Global'};
approx = buffer.approximationsGrid(grid.r, lambdaValues, nuValues, eta, ...
    {'Pade2', 'RBA2', 'ExpPade', 'DblExpGlobal', 'ExpGlobal'}, ...
    'PadeRefine', true, 'PadeRefineMethod', 'newton', ...
    'PadeRealCoefficients', true);

errors = cat(3, ...
    buffer.meanErrorGrid(bNum, real(approx.pade2)), ...
    buffer.meanErrorGrid(bNum, real(approx.rba2)), ...
    buffer.meanErrorGrid(bNum, real(approx.expPade)), ...
    buffer.meanErrorGrid(bNum, real(approx.doubleExpGlobal)), ...
    buffer.meanErrorGrid(bNum, real(approx.expGlobal)));

[winner, bestError] = buffer.winnerMap(errors);

colors = [0.47 0.67 0.19; ...
          0.85 0.33 0.10; ...
          0.50 0.50 0.50; ...
          0.75 0.00 0.75; ...
          0.00 0.00 0.90];

deltaVar    = buffer.doubleExpDiscriminant(lambdaValues, nuValues, eta, 'var');
deltaGlobal = buffer.doubleExpDiscriminant(lambdaValues, nuValues, eta, 'global');
contours = struct( ...
    'Z',         {deltaVar, deltaGlobal}, ...
    'Color',     {[0.85 0.85 0.85], [0.85 0.65 0.00]}, ...
    'LineWidth', {1.0, 1.0});

buffer.plotWinnerMap(nuValues, lambdaValues, winner, methodNames, colors, ...
    'Title', sprintf('Method regions (\\eta = %g)', eta), ...
    'Contours', contours, ...
    'OutputFile', fullfile(outDir, 'figure6A1A2_winnerMap.png'));

errorMap = log10(bestError);
errorMap = min(max(errorMap, -6), -2);

buffer.plotErrorMap(nuValues, lambdaValues, errorMap, ...
    'Title', 'log_{10}||b_{num} - b_{approx}||, \eta = 1', ...
    'CLim', [-6 -2], 'ColorTicks', -6:1:-2, ...
    'OutputFile', fullfile(outDir, 'figure6A1A2_errorMap.png'));
